/* Mind The Gap — Demo MVP 2026. No API keys in browser, all transactions simulated. */
'use strict';
const CFG=window.MTG_CONFIG||{};
const DBKEY='mtg-lean-mvp-v4';
const CATEGORIES=[
 ['price','Prezzo, costi e sostenibilità','prezzo, spese, imposte e budget'],
 ['space','Spazi e distribuzione','superficie, locali, piano, pertinenze'],
 ['location','Quartiere e collegamenti','posizione, servizi, mobilità'],
 ['condition','Stato e manutenzione','lavori, impianti e condizioni'],
 ['energy','Prestazione energetica','APE, classe energetica'],
 ['urban','Urbanistica e catasto','planimetria, titoli edilizi e agibilità'],
 ['condo','Condominio','spese, delibere, interventi e contenziosi'],
 ['risk','Rischi e verifiche','criticità tecniche, territoriali, vincoli'],
 ['legal','Condizioni di acquisto','occupazione, provenienza, tempistiche']
];
const PREFS=[['position','Posizione',5],['price','Prezzo rispetto al mio budget',5],['space','Spazi e distribuzione',4],['light','Luce naturale e atmosfera',4],['feel','Sensazione personale',4],['condition','Stato e lavori necessari',3],['commute','Tempi di percorrenza',3]];
const EXPERTS=[
 {id:'ex1',name:'Marco Bianchi',job:'Architetto',specialties:['urban','space','condition'],description:'Pratiche edilizie, modifiche interne, documentazione pre-offerta.',rating:4.9,reviews:24,quote:'«Mi ha aiutata a capire quali documenti chiedere prima della proposta.»',photo:'assets/expert-1.webp'},
 {id:'ex2',name:'Giulia Conti',job:'Geometra',specialties:['urban','legal','space'],description:'Identificativi catastali, planimetrie e verifiche documentali.',rating:4.8,reviews:31,quote:'«Molto utile avere un elenco preciso delle verifiche mancanti.»',photo:'assets/expert-2.webp'},
 {id:'ex3',name:'Luca Ferri',job:'Ingegnere edile',specialties:['risk','condition','energy'],description:'Difetti, lavori, impianti e analisi delle criticità dell’edificio.',rating:4.9,reviews:18,quote:'«La relazione era concreta e comprensibile.»',photo:'assets/expert-3.webp'},
 {id:'ex4',name:'Sara Ricci',job:'Consulente condominiale',specialties:['condo','legal','price'],description:'Spese condominiali, delibere e costi ricorrenti.',rating:4.7,reviews:16,quote:'«Ho chiarito i costi prima di fare l’offerta.»',photo:'assets/expert-4.webp'},
 {id:'ex5',name:'Paolo Moretti',job:'Consulente immobiliare',specialties:['price','location','legal'],description:'Analisi dei costi di acquisto e domande sulla proposta.',rating:4.8,reviews:22,quote:'«Mi ha aiutato a organizzare la negoziazione.»',photo:'assets/expert-5.webp'},
 {id:'ex6',name:'Elena Riva',job:'Tecnico energetico',specialties:['energy','condition','risk'],description:'APE, isolamento, interventi energetici e verifiche successive.',rating:4.9,reviews:13,quote:'«Indicazioni chiare sul tipo di verifica da richiedere.»',photo:'assets/expert-6.webp'}
];
const PACKS=[{id:'chat15',n:15,euro:5},{id:'chat40',n:40,euro:10},{id:'chat100',n:100,euro:20}];
const SERVICE=[{id:'message',name:'Consulenza via messaggi',price:49,desc:'Richiesta dimostrativa, nessuna chat professionale reale'},{id:'video',name:'Videocall',price:150,desc:'Interesse per una consulenza remota (prezzo-test)'},{id:'visit',name:'Sopralluogo',price:300,desc:'Interesse per un’ispezione (prezzo-test)'}];
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||('mtg-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),now=()=>new Date().toISOString(),money=n=>Number(n||0).toLocaleString('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const clone=v=>JSON.parse(JSON.stringify(v));
const newState=()=>({version:4,homes:[],events:[],freeUsed:0,credits:0,intents:[],createdAt:now()});
let S;try{S={...newState(),...JSON.parse(localStorage.getItem(DBKEY))}}catch{S=newState()}
let view='home',tab='overview',active=null,compareSelection=[],session=null,supabase=null;
function persist(){try{localStorage.setItem(DBKEY,JSON.stringify(S))}catch(e){console.error(e);toast('Spazio locale esaurito: esporta i tuoi dati.')}}
function track(type,extra={}){S.events.push({id:uid(),time:now(),type,...extra});persist()}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(window.__mtgt);window.__mtgt=setTimeout(()=>el.classList.remove('show'),4500)}
const getHome=id=>S.homes.find(h=>h.id===id),H=()=>getHome(active);
const authenticated=()=>!!session?.user;
const aiReady=()=>!!(CFG.supabaseUrl&&CFG.supabasePublishableKey);
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hide');$$('[data-close]').forEach(x=>x.onclick=closeModal)}
function closeModal(){$('#modal').classList.add('hide');$('#modalBody').innerHTML=''}
function validPortal(url){try{const u=new URL(url);if(u.protocol!=='https:')return false;return ['idealista.it','immobiliare.it'].some(d=>u.hostname===d||u.hostname.endsWith('.'+d))}catch{return false}}
function emptyHome(o={}){return{id:uid(),name:o.name||'Immobile da valutare',link:o.link||'',listingText:o.text||'',price:o.price||null,sqm:o.sqm||null,area:o.area||'',createdAt:now(),updatedAt:now(),prefs:Object.fromEntries(PREFS.map(([id,label,importance])=>[id,{importance,rating:3}])),docs:[],analysis:null,unlocked:false,reportScenario:false,expertReports:[],chat:[]}}
function fit(h){const prefs=Object.values(h.prefs||{});const denom=prefs.reduce((n,p)=>n+Number(p.importance||0),0);return denom?Math.round(prefs.reduce((n,p)=>n+Number(p.importance||0)*Number(p.rating||0),0)/denom*20):null}
function readiness(h){const analysis=h.analysis;if(!analysis)return null;const vals=CATEGORIES.map(([id])=>analysis.criteria?.[id]);let sum=0;for(const v of vals){const st=v?.status||'missing';sum+=({missing:0,declared:0.34,documented:0.69,expert_reviewed:1,conflict:0.12})[st]??0}return Math.round(sum/vals.length*100)}
function gapList(h){return h.analysis?.gaps||[]}
function badge(s){const klass=s==='high'?'high':s==='critical'?'critical':'';const name={critical:'Priorità critica',high:'Priorità alta',medium:'Da approfondire',low:'Informazione utile'}[s]||'Da approfondire';return `<span class="severity ${klass}">${name}</span>`}
function loading(label='Caricamento...'){return `<span class="loading">${safe(label)}</span>`}
function render(){const root=$('#app');root.innerHTML=view==='home'?homePage():view==='list'?listPage():view==='compare'?comparePage():view==='method'?methodPage():propertyPage();bind();$('#navAccount').textContent=authenticated()?'Il mio account':'Accedi';}
function go(p,id){view=p;if(id)active=id;tab='overview';render();window.scrollTo({top:0,behavior:'smooth'});if(p==='property')track('property_view',{propertyId:active})}
function homePage(){return `<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Mind The Gap · prima dell'offerta</div><h1>Ti piace questa casa.<br><span class="accent">Ma cosa non sai ancora?</span></h1><p class="lead">Un unico posto per confrontare le case, raccogliere i documenti e individuare le verifiche che contano davvero prima di fare un'offerta.</p><div class="chips"><span class="chip">✓ Prima analisi gratuita</span><span class="chip">✓ Preferenze anche emotive</span><span class="chip">✓ Dossier che si aggiorna</span></div></div><div class="card hero-form"><div class="eyebrow">Comincia da un immobile</div><h3>Hai già trovato una casa?</h3><p class="muted">Incolla la descrizione dell’immobile oppure carica il PDF dell’annuncio. Se hai solo il link, puoi salvarlo come riferimento (Beta).</p><form id="createForm"><div class="field"><label class="label">1. Descrizione dell’immobile</label><textarea id="homeText" placeholder="Incolla qui la descrizione dell’annuncio: superficie, prezzo, piano, condizioni, zona…"></textarea></div><div class="field"><label class="label">2. Oppure importa un PDF dell’annuncio</label><input id="initialPdf" type="file" class="input" accept=".pdf,.txt,application/pdf,text/plain"><p class="tiny">PDF con testo selezionabile, fino a 8 MB. Il file resta in questo browser e può essere rianalizzato più avanti.</p></div><div class="field"><label class="label">3. Link annuncio (Beta · facoltativo)</label><input class="input" id="homeLink" placeholder="https://www.idealista.it/immobile/..." type="url"><p class="tiny">Il link viene conservato, ma non ne garantiamo l’importazione automatica.</p></div><button class="btn btn-primary btn-full" type="submit">Ottieni la prima analisi →</button></form><p class="tiny mt2">L’analisi dal solo link è una funzione Beta non ancora operativa senza accesso autorizzato al portale.</p></div></div></section><div class="container section"><div class="section-head"><div class="eyebrow">Dall'annuncio alla decisione</div><h2>Non un semplice score. Un percorso.</h2></div><div class="grid grid-3"><div class="card"><div class="step-icon">01</div><h3>Scopri i gap</h3><p class="muted">L'AI separa le dichiarazioni dell'annuncio dalle evidenze e segnala cosa chiedere.</p></div><div class="card"><div class="step-icon">02</div><h3>Raccogli informazioni</h3><p class="muted">Aggiorna le preferenze e aggiungi PDF: il dossier si ricalcola.</p></div><div class="card"><div class="step-icon">03</div><h3>Confronta e approfondisci</h3><p class="muted">Confronta gli immobili e simula l'attivazione di consulenze mirate.</p></div></div><div class="grid grid-2 mt3"><div class="card"><div class="eyebrow">Per una scelta personale</div><h2>Property Fit</h2><p class="muted">Posizione, budget, spazi, luminosità, atmosfera e quello che per te è irrinunciabile. Preferenze modificabili nel tempo.</p></div><div class="card"><div class="eyebrow">Per una scelta informata</div><h2>Decision Readiness</h2><p class="muted">Quali informazioni sono documentate, quali sono solo dichiarate e quali rischi richiedono un professionista.</p></div></div></div>`}
function listPage(){return `<div class="container work-hero"><div class="flex between wrap"><div><div class="eyebrow">Workspace</div><h1 style="font-size:38px">I miei immobili</h1><p class="muted">Schede salvate nel browser in questa versione sperimentale.</p></div><button class="btn btn-primary" id="addHome">+ Nuovo immobile</button></div><div class="grid grid-3 mt3">${S.homes.length?S.homes.map(h=>`<div class="card"><div class="eyebrow">${safe(h.area||'Casa in valutazione')}</div><h3>${safe(h.name)}</h3><p class="muted">${h.price?money(h.price):'Prezzo da inserire'} · ${h.sqm?safe(h.sqm)+' m²':'Superficie da inserire'}</p><div class="flex mt2 wrap"><span class="chip">Fit ${fit(h)??'–'}/100</span><span class="chip">Dossier ${readiness(h)??'–'}/100</span></div><p class="small muted">${h.analysis?gapList(h).length+' gap individuati':'Analisi da eseguire'}</p><div class="flex mt2"><button class="btn btn-primary btn-small" data-open-home="${h.id}">Apri dossier</button><button class="btn btn-outline btn-small" data-delete="${h.id}">Elimina</button></div></div>`).join(''):'<div class="card"><h3>Non hai ancora aggiunto immobili</h3><p class="muted">Parti da un annuncio per creare il tuo primo dossier.</p><button class="btn btn-primary mt2" id="startFirst">Inizia</button></div>'}</div></div>`}
function headerH(h){return `<div class="container work-hero"><div class="flex between top wrap"><div><div class="eyebrow">Il tuo dossier immobiliare</div><h1 style="font-size:34px">${safe(h.name)}</h1><p class="muted">${safe(h.area||'Zona da precisare')} · ${h.price?money(h.price):'Prezzo da precisare'} ${h.sqm?' · '+safe(h.sqm)+' m²':''}</p></div><div class="flex wrap"><button class="btn btn-outline btn-small" id="editHome">Modifica dati</button><button class="btn btn-primary btn-small" id="rerun">↻ Aggiorna analisi AI</button></div></div><div class="subnav">${[['overview','Panoramica'],['gaps','Gap & dossier'],['preferences','Le tue preferenze'],['documents','Documenti'],['chat','Chiedi all’AI'],['experts','Esperti'],['compare','Confronto']].map(([id,label])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div></div>`}
function propertyPage(){const h=H();if(!h)return `<div class="container section">Immobile non trovato.</div>`;let body={overview:overviewTab,gaps:gapsTab,preferences:prefsTab,documents:documentsTab,chat:chatTab,experts:expertsTab,compare:compareInner}[tab](h);return headerH(h)+`<div class="container panel">${body}</div>`}
function scoreCard(title,score,sub){return `<div class="stat"><div class="flex between"><b>${title}</b><span class="num">${score===null?'—':score}<small style="font-size:15px">/100</small></span></div><div class="score-bar"><span style="width:${score||0}%"></span></div><p class="small muted">${sub}</p></div>`}
function decisionSteps(h){
 const g=gapList(h),critical=g.filter(x=>['critical','high'].includes(x.severity));
 return [
 {title:'Definisci cosa conta per te',done:!!h.prefs&&Object.keys(h.prefs).length>0,detail:'Le priorità razionali ed emotive possono cambiare nel tempo.',tab:'preferences'},
 {title:'Analizza l’immobile',done:!!h.analysis,detail:'Distingui caratteristiche dichiarate da evidenze disponibili.',tab:'gaps'},
 {title:'Integra i documenti mancanti',done:h.docs.length>0,detail:h.docs.length?`${h.docs.length} documenti aggiunti; verifica se coprono i gap.`:'Carica planimetria, APE o altri documenti ricevuti.',tab:'documents'},
 {title:'Affronta i gap prioritari',done:!!h.analysis&&critical.length===0,detail:critical.length?`${critical.length} gap importanti da approfondire. I report dimostrativi non li chiudono.`:'Nessun gap ad alta priorità attualmente segnalato; non equivale a certificazione.',tab:'gaps'},
 {title:'Rivedi la decisione',done:!!h.decisionReview,detail:'Registra la tua valutazione: procedere, approfondire oppure rinunciare.',tab:'overview'}
 ];
}
function nextDecisionAction(h){
 if(!h.analysis)return {title:'Analizza l’annuncio',text:'Inizia dalle informazioni dell’immobile per individuare le prime verifiche.',tab:'gaps'};
 const urgent=gapList(h).find(x=>['critical','high'].includes(x.severity));
 if(urgent)return {title:urgent.title,text:urgent.action||'Raccogli evidenze e valuta una verifica tecnica mirata.',tab:'gaps'};
 if(!h.docs.length)return {title:'Aggiungi i documenti dell’immobile',text:'Carica ciò che hai ricevuto e aggiorna l’analisi dei gap.',tab:'documents'};
 if(!h.decisionReview)return {title:'Rivedi la tua decisione',text:'Sulla base delle informazioni disponibili, scegli se procedere, approfondire o rinunciare.',tab:'overview'};
 return {title:'Continua a monitorare le evidenze',text:'La decisione resta modificabile: nuove informazioni possono cambiare la valutazione.',tab:'documents'};
}
function overviewTab(h){
 const g=gapList(h),steps=decisionSteps(h),done=steps.filter(s=>s.done).length,action=nextDecisionAction(h);
 return `<div class="card journey-hero"><div class="eyebrow">Il tuo percorso verso una decisione informata</div><div class="flex between wrap"><div><h2>Stai riducendo l’incertezza su questa casa</h2><p class="muted">Non devi raggiungere 100/100: devi capire quali aspetti contano e cosa rimane da verificare prima dell’offerta.</p></div><span class="chip">${done} di ${steps.length} fasi affrontate</span></div><div class="journey-track"><span style="width:${done/steps.length*100}%"></span></div><div class="journey-steps">${steps.map((x,i)=>`<button type="button" data-jump="${x.tab}" class="journey-step ${x.done?'done':''}"><span class="journey-number">${x.done?'✓':i+1}</span><span><b>${x.title}</b><small>${safe(x.detail)}</small></span></button>`).join('')}</div></div>
 <div class="grid grid-2 mt3">${scoreCard('Property Fit',fit(h),'Compatibilità con le tue preferenze. Dato inserito dal buyer.')}${scoreCard('Decision Readiness',readiness(h),'Copertura delle evidenze, non sicurezza tecnica o conformità.')}</div>
 <div class="card mt3 next-action"><div class="eyebrow">La tua prossima azione consigliata</div><h2>${safe(action.title)}</h2><p class="muted">${safe(action.text)}</p><button class="btn btn-primary mt2" data-jump="${action.tab}">Continua il percorso →</button></div>
 <div class="grid grid-2 mt3"><div class="card"><div class="eyebrow">Il quadro attuale</div><h3>${h.analysis?safe(h.analysis.preview||'Analisi preliminare disponibile'):'Analisi non ancora disponibile'}</h3><div class="chips mt2"><span class="chip">${g.filter(x=>['high','critical'].includes(x.severity)).length} gap prioritari</span><span class="chip">${h.docs.length} documenti</span><span class="chip">${h.expertReports.length} report dimostrativi</span></div><button class="btn btn-outline mt2" data-jump="gaps">Consulta il dossier</button></div><div class="card"><div class="eyebrow">Esito della decisione</div><h3>${safe(h.decisionReview?.label||'Non ancora espresso')}</h3><p class="muted">Non è un parere tecnico: registra come cambia la tua valutazione personale mentre raccogli le evidenze.</p><div class="flex wrap mt2"><button class="btn btn-outline btn-small" data-decision="proceed">Valuterei l’offerta</button><button class="btn btn-outline btn-small" data-decision="investigate">Devo approfondire</button><button class="btn btn-outline btn-small" data-decision="stop">Preferisco rinunciare</button></div></div></div>
 <div class="notice mt3">${h.analysis?.mode==='demo'?'Analisi dimostrativa: i gap non provengono da OpenAI finché non configuri Supabase e API.':'Un gap aperto non equivale a una non conformità. Il punteggio non sostituisce verifiche professionali.'}</div>`;
}
function gapsTab(h){const g=gapList(h);return `<div class="grid grid-2"><div><div class="flex between wrap mb2"><div><div class="eyebrow">Analisi dei rischi</div><h2>Gap da chiarire</h2></div><span class="chip">${g.length} identificati</span></div>${g.length?g.map((x,i)=>`<div class="gapitem"><div class="flex between top wrap"><h4>${safe(x.title)}</h4>${badge(x.severity)}</div><p class="small muted">${h.unlocked?safe(x.reason):i===0?safe(x.reason):'Approfondimento completo disponibile nel dossier.'}</p>${h.unlocked?`<p class="small"><b>Azione:</b> ${safe(x.action)}</p><p class="tiny">Fonte: ${safe(x.source||'Annuncio e documenti forniti')} · Stato: ${safe(x.status||'aperto')}</p><button class="btn btn-outline btn-small mt2" data-experts-gap="${safe(x.category)}">Trova un esperto per questo gap</button>`:i>0?'<span class="tiny">Dettagli riservati al dossier completo</span>':''}</div>`).join(''):'<div class="card">Nessun gap disponibile: esegui prima l’analisi.</div>'}</div><div><div class="card"><div class="eyebrow">Dossier dinamico</div><h3>La tua analisi si aggiorna con le evidenze</h3><p class="muted">Il sistema distingue documenti dichiarati, ricevuti e realmente verificati. Un documento aggiuntivo può cambiare i gap ma non certifica automaticamente nulla.</p>${!h.unlocked?`<div class="paywall mt3"><div class="eyebrow" style="color:#9ddacc">Dossier completo · prezzo-test</div><h2>49 €</h2><p class="muted">Tutte le spiegazioni, azioni consigliate, confronto completo ed esportazione del dossier.</p><button class="btn btn-primary btn-full mt2" id="unlockDossier">Simula l'acquisto del dossier →</button><p class="tiny">Nessun addebito. Registriamo solo l'intenzione d'acquisto.</p></div>`:`<div class="notice mt2">Dossier sbloccato per simulazione. Nessun pagamento reale effettuato.</div><button class="btn btn-outline mt2" id="exportDossier">Esporta dossier (.txt)</button>`}</div><div class="card mt2"><h3>Consigli testuali AI</h3><p class="muted">Chiedi quale documento serve o come preparare una domanda all’esperto, usando il contesto del tuo immobile.</p><button class="btn btn-outline mt2" data-jump="chat">Apri la chat AI</button></div></div></div>`}
function prefsTab(h){return `<div class="flex between wrap mb2"><div><div class="eyebrow">Razionalità + emotività</div><h2>Che cosa conta per te?</h2></div><span class="chip">Fit ${fit(h)}/100</span></div><div class="card"><p class="muted">Per ogni dimensione scegli quanto pesa nella tua decisione e quanto l'immobile ti soddisfa oggi. Le preferenze rimangono modificabili.</p>${PREFS.map(([id,label])=>{const p=h.prefs[id]||{importance:3,rating:3};return `<div class="pref-row"><div><b>${safe(label)}</b></div><div><label class="label">Importanza: <span id="iw-${id}">${p.importance}</span>/5</label><input type="range" min="0" max="5" value="${p.importance}" data-pref="${id}" data-kind="importance"></div><div><label class="label">Valutazione: <span id="rw-${id}">${p.rating}</span>/5</label><input type="range" min="0" max="5" value="${p.rating}" data-pref="${id}" data-kind="rating"></div></div>`}).join('')}<p class="tiny mt2">Il Property Fit misura le valutazioni inserite dal buyer. Non è una verifica oggettiva, né un punteggio assegnato dall'AI.</p></div>`}
function documentsTab(h){return `<div class="grid grid-2"><div class="card"><div class="eyebrow">Documenti nel tempo</div><h2>Aggiungi una nuova evidenza</h2><p class="muted">Carica PDF testuali o TXT. Il testo viene conservato localmente in IndexedDB su questo dispositivo e usato nelle analisi successive.</p><div class="field"><label class="label">Documento</label><input type="file" id="docUpload" accept=".pdf,.txt,application/pdf,text/plain" class="input"></div><button id="uploadDoc" class="btn btn-primary">Aggiungi documento</button><p class="tiny mt2">Per questo MVP il salvataggio non è sincronizzato su altri dispositivi. Non utilizzare documenti sensibili senza una adeguata configurazione privacy.</p></div><div class="card"><div class="eyebrow">Documenti raccolti</div><h3>${h.docs.length} documenti</h3>${h.docs.map(d=>`<div class="file-row flex between"><div><b>${safe(d.name)}</b><div class="tiny">${safe(d.date.slice(0,10))} · ${safe(d.kind||'Documento')}</div></div><button class="btn btn-outline btn-small" data-remove-doc="${d.id}">Rimuovi</button></div>`).join('')||'<p class="muted">Nessun documento ancora aggiunto.</p>'}<button class="btn btn-outline mt2" id="rerunFromDocs">Rianalizza con i documenti</button></div></div>`}
function chatTab(h){const remaining=Math.max(0,3-S.freeUsed)+S.credits;return `<div class="grid grid-2"><div class="chatbox"><div class="flex between" style="padding:18px;border-bottom:1px solid var(--border)"><div><b>Chiedi all'AI del tuo immobile</b><div class="tiny">Risposte contestualizzate su annunci, gap e documenti</div></div><span class="chip">${remaining} risposte disponibili</span></div><div class="messages" id="chatMessages">${h.chat.length?h.chat.map(m=>`<div class="bubble ${m.role==='user'?'user':'assistant'}">${safe(m.text)}</div>`).join(''):'<div class="notice">Puoi chiedere ad esempio: «Quali informazioni devo richiedere prima della proposta?»</div>'}</div><form id="chatForm" class="chat-compose"><textarea id="chatQuestion" placeholder="Scrivi la tua domanda..." maxlength="1200"></textarea><button class="btn btn-primary" ${remaining<=0?'disabled':''}>Invia</button></form></div><div><div class="card"><div class="eyebrow">Il tuo piano AI</div><h3>${Math.max(0,3-S.freeUsed)} risposte iniziali gratuite + ${S.credits} acquistate in simulazione</h3><p class="muted">Le prime 3 risposte sono gratis per questo browser. Dopo puoi simulare l'acquisto di un pacchetto; nessuna transazione reale.</p><div class="grid grid-3 mt2">${PACKS.map(p=>`<div class="pack"><b>${money(p.euro)}</b><span>${p.n} domande</span><button class="btn btn-outline btn-small mt2" data-pack="${p.id}">Scegli</button></div>`).join('')}</div><p class="tiny mt2">Nella demo il conteggio è conservato localmente e può essere azzerato: non è un sistema antifrode o un paywall commerciale sicuro.</p></div><div class="notice mt2">Le risposte AI non sostituiscono la valutazione di un tecnico. I dettagli premium non sono forniti alla chat gratuita prima dello sblocco del dossier.</div></div></div>`}
function rankExperts(h,cat){return [...EXPERTS].sort((a,b)=>Number(b.specialties.includes(cat))-Number(a.specialties.includes(cat))||b.rating-a.rating)}
function expertsTab(h){const first=gapList(h)[0]?.category||'urban';return `<div class="flex between wrap mb2"><div><div class="eyebrow">Assistenza professionale</div><h2>Trova la specializzazione giusta</h2><p class="muted">I profili sono suggeriti in base ai gap rilevati nell'immobile.</p></div><div><label class="label">Filtra per gap</label><select class="input" id="expertFilter"><option value="all">Tutte le specializzazioni</option>${CATEGORIES.map(([id,label])=>`<option value="${id}" ${id===first?'selected':''}>${safe(label)}</option>`).join('')}</select></div></div><div class="notice mb2">I nomi, le fotografie e le recensioni riportati sotto sono simulati e servono soltanto a testare il percorso MVP. Nessun professionista è realmente prenotabile.</div><div class="grid grid-3" id="expertGrid">${expertCards(rankExperts(h,first),first)}</div><div class="card mt3"><h3>Report dell'esperto</h3><p class="muted">Dopo una richiesta simulata puoi integrare un esempio di report strutturato; l'analisi viene aggiornata in modalità scenario, senza presentare il report come una verifica reale.</p>${h.expertReports.map((r,i)=>`<div class="file-row"><b>${safe(r.expertName)}</b> · ${safe(r.categoryLabel)} · ${safe(r.date.slice(0,10))}<p class="small muted">${safe(r.summary)}</p><span class="chip">Report dimostrativo integrato</span></div>`).join('')||'<p class="tiny">Non hai ancora integrato report dimostrativi.</p>'}</div>`}
function expertCards(arr,cat){return arr.slice(0,6).map((e,i)=>`<div class="card expert-card"><div class="expert-head"><img class="pro-image" src="${e.photo}" alt="Ritratto illustrativo del professionista simulato"><div><strong>${safe(e.name)}</strong><div class="small muted">${safe(e.job)}</div><div class="stars">★ ${e.rating.toFixed(1).replace('.',',')} · ${e.reviews} recensioni</div></div></div><p class="small muted">${safe(e.description)}</p><div class="chips mt2">${e.specialties.map(c=>`<span class="tag">${safe(CATEGORIES.find(x=>x[0]===c)?.[1]||c)}</span>`).join('')}</div><p class="small">${safe(e.quote)}</p><button class="btn btn-primary btn-full mt2" data-book="${e.id}" data-cat="${cat}">Vedi servizi e prezzi</button><div class="tiny mt2">Profilo e recensioni simulati per MVP</div></div>`).join('')}
function compareInner(){return `<div class="card"><h2>Confronta gli immobili</h2><p class="muted">Seleziona due o tre immobili per verificare compromessi, preferenze e gap prioritari.</p><button class="btn btn-primary mt2" id="openCompare">Apri confronto</button></div>`}
function comparePage(){const homes=S.homes;const selected=homes.filter(h=>compareSelection.includes(h.id));return `<div class="container work-hero"><div class="eyebrow">Una decisione, più alternative</div><h1 style="font-size:38px">Confronta le case</h1><p class="muted">Scegli da due a tre immobili: Fit, Readiness, gap aperti e costi non vengono fusi in un voto unico.</p><div class="card mt3"><div class="flex wrap">${homes.map(h=>`<label class="chip" style="cursor:pointer"><input type="checkbox" data-compare-select="${h.id}" ${compareSelection.includes(h.id)?'checked':''}> ${safe(h.name)}</label>`).join('')||'Nessun immobile da confrontare.'}</div><button class="btn btn-primary mt2" id="runCompare" ${selected.length<2?'disabled':''}>Confronta ${selected.length} immobili</button></div>${selected.length>=2?`<div class="card mt3 table-scroll"><table><thead><tr><th>Elemento</th>${selected.map(h=>`<th>${safe(h.name)}</th>`).join('')}</tr></thead><tbody>${[['Prezzo',h=>h.price?money(h.price):'N/D'],['Superficie',h=>h.sqm?h.sqm+' m²':'N/D'],['Property Fit',h=>(fit(h)??'–')+'/100'],['Decision Readiness',h=>(readiness(h)??'–')+'/100'],['Gap prioritari',h=>gapList(h).filter(g=>['high','critical'].includes(g.severity)).length],['Documenti',h=>h.docs.length],['Report esperti (simulati)',h=>h.expertReports.length]].map(([l,fn])=>`<tr><td><b>${l}</b></td>${selected.map(h=>`<td>${safe(fn(h))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice mt2">Per ragioni di confrontabilità, i punteggi Fit dipendono dalle preferenze inserite per ciascuna casa: allinea i pesi prima di trarre conclusioni.</div>`:''}</div>`}
function methodPage(){return `<div class="container section"><div class="eyebrow">Approccio MTG</div><h1 style="font-size:44px">Come prende forma una decisione</h1><div class="grid grid-3 mt3"><div class="card"><h3>1. Dati e preferenze</h3><p class="muted">Raccogliamo quello che l'immobile dichiara e quello che per te conta davvero, incluse le emozioni.</p></div><div class="card"><h3>2. Evidenze e gap</h3><p class="muted">Una checklist documentale aiuta a identificare quello che manca. L'AI suggerisce approfondimenti, non certifica la conformità.</p></div><div class="card"><h3>3. Azioni e confronto</h3><p class="muted">Aggiungi nuovi documenti, confronta le opzioni e simula richieste a professionisti specializzati.</p></div></div><div class="card mt3"><h2>Come funziona il test MVP</h2><p>Prezzi, recensioni professionali, acquisti, prenotazioni e report degli esperti sono <b>simulati</b>. Il clic su un prezzo registra un'intenzione di pagamento e sblocca le funzioni senza addebiti. Non vengono erogati servizi professionali reali.</p><p>Quando OpenAI e Supabase sono configurati, l'analisi testuale AI usa il backend protetto. In assenza di configurazione viene mostrata una demo euristica, identificata come tale.</p><button class="btn btn-outline mt2" id="exportEvents">Esporta eventi del test (JSON)</button></div></div>`}
function bind(){if(view==='home'){$('#createForm').onsubmit=createHome}if(view==='list'){$('#addHome').onclick=()=>go('home');$('#startFirst')?.addEventListener('click',()=>go('home'));$$('[data-open-home]').forEach(b=>b.onclick=()=>go('property',b.dataset.openHome));$$('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Eliminare l’immobile da questo browser?')){S.homes=S.homes.filter(h=>h.id!==b.dataset.delete);persist();render()}})}if(view==='compare'){$$('[data-compare-select]').forEach(b=>b.onchange=()=>{compareSelection=b.checked?[...new Set([...compareSelection,b.dataset.compareSelect])].slice(0,3):compareSelection.filter(id=>id!==b.dataset.compareSelect);render()});$('#runCompare').onclick=()=>{track('compare_view',{properties:compareSelection})}}if(view==='method'){$('#exportEvents').onclick=()=>downloadJSON('mtg-events.json',{events:S.events,notice:'Intentions and simulated purchases; no payments captured'})}if(view==='property')bindProperty()}
function bindProperty(){const h=H();$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();track('tab_view',{tab,propertyId:h.id})});$$('[data-jump]').forEach(b=>b.onclick=()=>{tab=b.dataset.jump;render()});$('#rerun').onclick=()=>analyze(h);$('#editHome').onclick=()=>editHome(h);if(tab==='overview'){$$('[data-decision]').forEach(b=>b.onclick=()=>{const labels={proceed:'Valuterei l’offerta',investigate:'Devo approfondire',stop:'Preferisco rinunciare'};h.decisionReview={choice:b.dataset.decision,label:labels[b.dataset.decision],date:now(),readiness:readiness(h),fit:fit(h)};track('decision_review',{propertyId:h.id,choice:b.dataset.decision,readiness:readiness(h)});persist();render()})}if(tab==='gaps'){$('#unlockDossier')?.addEventListener('click',()=>intentDossier(h));$('#exportDossier')?.addEventListener('click',()=>exportDossier(h));$$('[data-experts-gap]').forEach(b=>b.onclick=()=>{tab='experts';render();$('#expertFilter').value=b.dataset.expertsGap;$('#expertFilter').dispatchEvent(new Event('change'))})}if(tab==='preferences'){$$('[data-pref]').forEach(input=>input.oninput=()=>{const k=input.dataset.pref,type=input.dataset.kind;h.prefs[k][type]=Number(input.value);h.updatedAt=now();persist();$(`#${type==='importance'?'iw':'rw'}-${k}`).textContent=input.value;track('preference_update',{propertyId:h.id,key:k,kind:type,value:Number(input.value)})});}if(tab==='documents'){$('#uploadDoc').onclick=()=>uploadDocument(h);$('#rerunFromDocs').onclick=()=>analyze(h);$$('[data-remove-doc]').forEach(b=>b.onclick=async()=>{await deleteDocument(h.id,b.dataset.removeDoc);h.docs=h.docs.filter(d=>d.id!==b.dataset.removeDoc);persist();render()})}if(tab==='chat'){$('#chatForm').onsubmit=e=>sendChat(e,h);$$('[data-pack]').forEach(b=>b.onclick=()=>intentPack(b.dataset.pack));const m=$('#chatMessages');m.scrollTop=m.scrollHeight}if(tab==='experts'){$('#expertFilter').onchange=e=>{$('#expertGrid').innerHTML=expertCards(rankExperts(h,e.target.value),e.target.value);bindExpertCards()};bindExpertCards()}if(tab==='compare')$('#openCompare').onclick=()=>{compareSelection=[h.id,...S.homes.filter(x=>x.id!==h.id).map(x=>x.id)].slice(0,3);go('compare')}}
async function createHome(e){
 e.preventDefault();const button=$('#createForm button[type="submit"]');button.disabled=true;
 try{
   const link=$('#homeLink').value.trim();let text=$('#homeText').value.trim();const f=$('#initialPdf')?.files?.[0];
   if(link&&!validPortal(link))throw Error('Inserisci un link HTTPS di Idealista o Immobiliare.it');
   let extracted='';if(f)extracted=await parseUpload(f);
   if(!text&&!extracted&&!link)throw Error('Incolla una descrizione, carica un PDF o salva un link Beta');
   if(extracted)text=(text?text+'\n\n':'')+'[Testo estratto da '+f.name+']\n'+extracted;
   const h=emptyHome({link,text,name:text.match(/(?:bilocale|trilocale|quadrilocale|appartamento|attico|loft|villetta|villa)/i)?.[0]||'Nuovo immobile'});
   if(f){const id=uid();await storeDocument(h.id+':'+id,extracted);h.docs.push({id,name:f.name,date:now(),kind:'PDF annuncio',chars:extracted.length})}
   S.homes.unshift(h);persist();track('property_created',{propertyId:h.id,hasLink:!!link,hasDescription:!!text,hasInitialPdf:!!f});go('property',h.id);
   if(text)await analyze(h);else{toast('Link Beta salvato: aggiungi descrizione o PDF per avviare l’analisi.');editHome(h)}
 }catch(err){toast(err.message||'Errore durante il caricamento')}finally{if(button.isConnected)button.disabled=false}
}
function editHome(h){openModal(`<div class="flex between"><h2>Dati dell’immobile</h2><button class="btn btn-outline btn-small" data-close>Chiudi</button></div><div class="field"><label class="label">Nome</label><input class="input" id="eName" value="${safe(h.name)}"></div><div class="field"><label class="label">Zona / indirizzo approssimativo</label><input class="input" id="eArea" value="${safe(h.area)}"></div><div class="grid grid-2"><div class="field"><label class="label">Prezzo €</label><input class="input" type="number" id="ePrice" value="${h.price||''}"></div><div class="field"><label class="label">Superficie m²</label><input class="input" type="number" id="eSqm" value="${h.sqm||''}"></div></div><div class="field"><label class="label">Link annuncio</label><input class="input" id="eLink" value="${safe(h.link)}"></div><div class="field"><label class="label">Descrizione / testo annuncio</label><textarea id="eText">${safe(h.listingText)}</textarea></div><button class="btn btn-primary btn-full" id="saveEdits">Salva e analizza</button>`);$('#saveEdits').onclick=()=>{const link=$('#eLink').value.trim();if(link&&!validPortal(link))return toast('Link non riconosciuto');Object.assign(h,{name:$('#eName').value.trim()||h.name,area:$('#eArea').value.trim(),price:Number($('#ePrice').value)||null,sqm:Number($('#eSqm').value)||null,link,listingText:$('#eText').value.trim(),updatedAt:now()});persist();closeModal();render();analyze(h)}}
async function openDocDB(){return await new Promise((res,rej)=>{const req=indexedDB.open('mtg-doc-text',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'key'});req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
async function storeDocument(key,text){const db=await openDocDB();await new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({key,text});tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});db.close()}
async function readDocument(key){const db=await openDocDB();let result=await new Promise((res,rej)=>{const tx=db.transaction('files');const req=tx.objectStore('files').get(key);req.onsuccess=()=>res(req.result?.text||'');req.onerror=()=>rej(req.error)});db.close();return result}
async function deleteDocument(homeId,docId){const db=await openDocDB();await new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(homeId+':'+docId);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});db.close()}
async function parseUpload(f){if(f.size>8*1024*1024)throw Error('File troppo grande (massimo 8 MB)');if(f.name.toLowerCase().endsWith('.txt'))return (await f.text()).slice(0,45000);if(!f.name.toLowerCase().endsWith('.pdf'))throw Error('Sono supportati PDF testuali e TXT');const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs';const doc=await pdfjs.getDocument({data:new Uint8Array(await f.arrayBuffer())}).promise;let text='';for(let i=1;i<=Math.min(doc.numPages,20);i++){const p=await doc.getPage(i);const c=await p.getTextContent();text+='\n'+c.items.map(x=>x.str||'').join(' ');if(text.length>45000)break}if(text.trim().length<35)throw Error('PDF scansito o senza testo: serve OCR o un PDF testuale.');return text.slice(0,45000)}
async function uploadDocument(h){const file=$('#docUpload').files?.[0];if(!file)return toast('Seleziona prima un PDF o TXT');const b=$('#uploadDoc');b.disabled=true;b.textContent='Lettura del documento...';try{const text=await parseUpload(file);const d={id:uid(),name:file.name,date:now(),kind:'Documento buyer',size:file.size};await storeDocument(h.id+':'+d.id,text);h.docs.push(d);h.updatedAt=now();persist();track('document_uploaded',{propertyId:h.id,extension:file.name.split('.').pop()});render();toast('Documento aggiunto. Rianalizza per aggiornare i gap.')}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Aggiungi documento'}}
function demoAnalyze(h){let text=(h.listingText||'').toLowerCase();const checks={price:/prezzo|€|euro|mutuo|spes[ae]/,space:/mq|m²|metri quadri|locali|piano|camera/,location:/milano|quartiere|metro|zona|comune|indirizzo/,condition:/ristrutturat|buon[eo] stat|impiant|da ristrutturare/,energy:/ape|classe energetica|kwh/,urban:/planimetr|catastal|conformità|agibilit|titolo edilizio/,condo:/condomin|assemblea|spese ordinarie/,risk:/amianto|alluvion|vincol|umidit|crepe|rischi/,legal:/rogito|libero|occupat|vendit|consegna/};let criteria={};for(const [id] of CATEGORIES)criteria[id]={status:checks[id].test(text)?'declared':'missing',evidence:checks[id].test(text)?'Parola chiave nell’annuncio':'Non presente nell’annuncio'};const fromDocs=new Set(h.docs.flatMap(d=>{const low=d.name.toLowerCase();return CATEGORIES.filter(([id,label])=>low.includes(id)||low.includes(label.toLowerCase().split(' ')[0])).map(x=>x[0])}));for(const id of fromDocs)criteria[id].status='documented';const gaps=CATEGORIES.filter(([id])=>criteria[id].status==='missing').map(([id,title])=>({id,category:id,title:'Da chiarire: '+title,severity:['urban','risk','legal'].includes(id)?'high':'medium',reason:'L’annuncio non contiene evidenze sufficienti per valutare: '+title.toLowerCase()+'.',action:'Chiedi la documentazione pertinente e, se necessario, incarica un professionista.',source:'Annuncio fornito',status:'aperto'}));if(h.expertReports.length)for(const r of h.expertReports){const g=gaps.find(x=>x.category===r.category);if(g){g.reason+=' È presente un report dimostrativo che non costituisce verifica reale.';g.status='scenario';criteria[r.category].status='declared'}}return {mode:'demo',criteria,gaps,preview:`Anteprima dimostrativa: ${gaps.length} aree senza informazioni sufficienti.`,recommendations:['Chiedi i documenti originali prima di un’offerta vincolante.','Prioritizza le verifiche in base ai rischi effettivi e alle tue esigenze.'],generatedAt:now()}}
async function docContext(h){const items=[];for(const d of h.docs){const t=await readDocument(h.id+':'+d.id).catch(()=>'');if(t)items.push({name:d.name,text:t.slice(0,12000),kind:'buyer_document'})}return items.slice(0,8)}
async function startAuth(){if(!aiReady())return toast('Per attivare OpenAI configura Supabase in config.js');if(!supabase)return toast('Supabase non disponibile');openModal(`<div class="flex between"><h2>Accedi a MTG</h2><button class="btn btn-outline btn-small" data-close>Chiudi</button></div><p class="muted">Per usare l'analisi AI reale devi accedere con email. Puoi provare la demo senza account.</p><div class="field"><label class="label">Email</label><input class="input" id="authEmail" type="email"></div><button class="btn btn-primary btn-full" id="sendLogin">Invia link di accesso</button>`);$('#sendLogin').onclick=async()=>{const email=$('#authEmail').value.trim();if(!email.includes('@'))return toast('Inserisci una email valida');const {error}=await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname}});if(error)toast(error.message);else{closeModal();toast('Controlla la casella email.')}}}
async function useAI(operation,body){if(!aiReady())throw Error('AI non configurata');if(!authenticated()){startAuth();throw Error('Accedi prima di usare OpenAI')}const {data,error}=await supabase.functions.invoke('mtg-ai',{body:{operation,...body}});if(error){let msg=error.message;try{msg=(await error.context.json()).error||msg}catch{}throw Error(msg)}if(data?.error)throw Error(data.error);return data}
async function analyze(h){const old=$('#rerun');if(old){old.disabled=true;old.textContent='Analisi in corso...'}track('analysis_attempt',{propertyId:h.id});try{if(!h.listingText.trim()&&!h.docs.length){toast('Aggiungi la descrizione dell’annuncio o un documento. Dal solo URL non possiamo garantire l’importazione.');return}let analysis;if(aiReady()&&authenticated()){const result=await useAI('analyze',{property:{id:h.id,link:h.link,description:h.listingText,price:h.price,sqm:h.sqm,area:h.area},documents:await docContext(h),reports:h.expertReports.map(r=>({...r,simulation:true})),unlocked:h.unlocked});analysis=result.analysis;if(!analysis?.criteria||!Array.isArray(analysis.gaps))throw Error('Formato di analisi non valido')}else{analysis=demoAnalyze(h);toast('Analisi dimostrativa (senza OpenAI). Accedi e configura il backend per usare l’AI reale.')}h.analysis=analysis;h.updatedAt=now();persist();track('analysis_completed',{propertyId:h.id,mode:analysis.mode,gaps:analysis.gaps.length});render()}catch(e){toast('Analisi non riuscita: '+e.message)}finally{const b=$('#rerun');if(b){b.disabled=false;b.textContent='↻ Aggiorna analisi AI'}}}
function confirmIntent(title,price,detail,fn){openModal(`<div class="flex between"><h2>${safe(title)}</h2><button class="btn btn-outline btn-small" data-close>Chiudi</button></div><div class="price">${money(price)}</div><p class="muted">${safe(detail)}</p><div class="notice warn mt2"><b>Test MVP — nessun pagamento reale.</b> Premendo «Confermo l'intenzione» registreremo la tua scelta e sbloccheremo le funzionalità previste nella simulazione.</div><button class="btn btn-primary btn-full mt3" id="confirmIntent">Confermo l'intenzione di pagamento</button><button class="btn btn-ghost btn-full mt2" data-close>Annulla</button>`);$('#confirmIntent').onclick=()=>{fn();closeModal();render()}}
function intentDossier(h){track('offer_view',{propertyId:h.id,offer:'dossier',price:49});confirmIntent('Dossier completo',49,'Gap completi, azioni consigliate, fonti ed esportazione del dossier.',()=>{h.unlocked=true;S.intents.push({id:uid(),time:now(),type:'dossier',propertyId:h.id,price:49});track('payment_intent',{propertyId:h.id,product:'dossier',price:49,realPayment:false});persist();toast('Dossier sbloccato in simulazione')})}
function intentPack(id){const p=PACKS.find(x=>x.id===id);if(!p)return;track('offer_view',{offer:p.id,price:p.euro});confirmIntent(`${p.n} risposte AI`,p.euro,`Aggiungi ${p.n} risposte al tuo conto dimostrativo.`,()=>{S.credits+=p.n;S.intents.push({id:uid(),time:now(),type:p.id,price:p.euro});track('payment_intent',{product:p.id,price:p.euro,realPayment:false});persist();toast(`${p.n} crediti demo aggiunti`)})}
function sendChat(e,h){e.preventDefault();const q=$('#chatQuestion').value.trim();if(!q||q.length<5)return toast('Scrivi una domanda più completa');if(S.freeUsed>=3&&S.credits<=0){toast('Hai esaurito le risposte. Scegli un pacchetto dimostrativo.');return}const send=$('#chatForm button');send.disabled=true;const isReal=aiReady()&&authenticated();const run=async()=>{try{let answer;if(isReal){const x=await useAI('chat',{question:q,property:{id:h.id,description:h.listingText,area:h.area,price:h.price,sqm:h.sqm},analysis:h.unlocked?h.analysis:{preview:h.analysis?.preview,gapCount:gapList(h).length,firstGap:gapList(h)[0]},history:h.chat.slice(-8),unlocked:h.unlocked});answer=x.answer||'Non sono riuscito a formulare una risposta.'}else{answer=`[RISPOSTA DEMO] Per «${q.slice(0,85)}»: prima dell'offerta verifica i documenti non disponibili, richiedi spiegazioni puntuali e valuta un esperto per i gap più rilevanti. Questa risposta non proviene da OpenAI.`}if(S.freeUsed<3)S.freeUsed++;else S.credits--;h.chat.push({role:'user',text:q,at:now()},{role:'assistant',text:answer,at:now()});track('chat_answer',{propertyId:h.id,mode:isReal?'ai':'demo',freeUsed:S.freeUsed,credits:S.credits});persist();render();const m=$('#chatMessages');m.scrollTop=m.scrollHeight}catch(e){toast('Risposta non disponibile: '+e.message);send.disabled=false}};run()}
function bindExpertCards(){$$('[data-book]').forEach(b=>b.onclick=()=>expertModal(b.dataset.book,b.dataset.cat))}
function expertModal(id,cat){const e=EXPERTS.find(x=>x.id===id),label=CATEGORIES.find(x=>x[0]===cat)?.[1]||'gap da chiarire',h=H();if(!e)return;track('expert_profile_view',{expertId:e.id,category:cat,propertyId:h.id});openModal(`<div class="flex between"><h2>Servizi di ${safe(e.name)}</h2><button class="btn btn-outline btn-small" data-close>Chiudi</button></div><div class="flex top"><img class="pro-image" src="${e.photo}"><div><b>${safe(e.job)}</b><p class="small muted">Consigliato per: ${safe(label)}</p><div class="stars">★ ${e.rating.toFixed(1).replace('.',',')} · ${e.reviews} recensioni</div></div></div><div class="notice mt2">Professionista e recensioni simulati. Prezzi sperimentali, non tariffe concordate.</div><div class="grid mt2">${SERVICE.map(s=>`<div class="file-row flex between wrap"><div><b>${safe(s.name)}</b><div class="tiny">${safe(s.desc)}</div></div><div class="flex"><b>${money(s.price)}</b><button class="btn btn-primary btn-small" data-expert-svc="${s.id}">Seleziona</button></div></div>`).join('')}</div><p class="tiny">Il listino deriva da ipotesi di test e da fasce WTP buyer, non da accordi con professionisti reali.</p>`);$$('[data-expert-svc]').forEach(b=>b.onclick=()=>intentExpert(e,cat,b.dataset.expertSvc))}
function intentExpert(e,cat,serviceId){const s=SERVICE.find(x=>x.id===serviceId),h=H();if(!s)return;track('expert_offer_view',{expertId:e.id,propertyId:h.id,service:serviceId,price:s.price});confirmIntent(`${s.name} · ${e.name}`,s.price,`Richiesta simulata relativa a: ${CATEGORIES.find(x=>x[0]===cat)?.[1]||'gap tecnico'}. Nessuna chat, videocall o ispezione sarà effettivamente erogata.`,()=>{S.intents.push({id:uid(),time:now(),type:'expert',propertyId:h.id,expertId:e.id,service:serviceId,category:cat,price:s.price});track('payment_intent',{product:'expert_'+serviceId,propertyId:h.id,price:s.price,realPayment:false});persist();setTimeout(()=>demoExpertReportOffer(e,cat,serviceId),150)})}
function demoExpertReportOffer(e,cat,serviceId){const h=H();openModal(`<h2>Richiesta registrata</h2><div class="notice">Hai espresso un'intenzione di pagamento. Non è stato effettuato alcun addebito né erogato un servizio professionale.</div><p>Per continuare il test puoi integrare un <b>report professionale dimostrativo</b> nel dossier e vedere come cambierebbe l'analisi.</p><button class="btn btn-primary btn-full mt2" id="integrateExpert">Verifica report dell'esperto (simulazione)</button><button class="btn btn-outline btn-full mt2" data-close>Non adesso</button>`);$('#integrateExpert').onclick=async()=>{const report={id:uid(),expertId:e.id,expertName:e.name,category:cat,categoryLabel:CATEGORIES.find(x=>x[0]===cat)?.[1]||cat,service:serviceId,date:now(),simulation:true,summary:`Documento illustrativo per ${cat}: le informazioni presenti non consentono di certificare la conformità dell’immobile. È necessario acquisire le evidenze originali e, dove previsto, eseguire un sopralluogo o una verifica da professionista abilitato.`,findings:[{item:'Evidenza documentale',status:'da approfondire',source:'Scenario dimostrativo',action:'Richiedere il documento originale e verificarlo'}]};h.expertReports.push(report);h.reportScenario=true;persist();track('expert_report_demo_integrated',{propertyId:h.id,category:cat});closeModal();toast('Report dimostrativo integrato: aggiorno l’analisi.');await analyze(h);tab='experts';render()}}
function exportDossier(h){if(!h.unlocked)return toast('Dossier non sbloccato');const t=[`MIND THE GAP — DOSSIER SPERIMENTALE`,h.name,h.link,`Property Fit: ${fit(h)}/100`,`Decision Readiness: ${readiness(h)??'—'}/100`,h.analysis?.mode==='demo'?'ANALISI DEMO (NON AI)':'ANALISI PRELIMINARE AI','',...gapList(h).flatMap(g=>[g.title,g.reason,'Azione: '+g.action,'Fonte: '+(g.source||'non specificata'),'']),...h.expertReports.map(r=>'REPORT DIMOSTRATIVO: '+r.summary),'',`Le informazioni non costituiscono perizia tecnica.`].join('\n');const u=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='MTG_Dossier_'+h.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);track('dossier_export',{propertyId:h.id})}
function downloadJSON(name,o){const u=URL.createObjectURL(new Blob([JSON.stringify(o,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
async function initSupabase(){if(!aiReady())return;try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2');supabase=createClient(CFG.supabaseUrl,CFG.supabasePublishableKey);const {data}=await supabase.auth.getSession();session=data.session;supabase.auth.onAuthStateChange((_,newSession)=>{session=newSession;$('#navAccount').textContent=authenticated()?'Il mio account':'Accedi'});render()}catch(e){console.error(e);toast('Supabase non disponibile: puoi usare la demo locale.')}}
$('#brand').onclick=e=>{e.preventDefault();go('home')};$('#navHomes').onclick=()=>go('list');$('#navCompare').onclick=()=>go('compare');$('#navMethod').onclick=()=>go('method');$('#navAccount').onclick=()=>{if(!authenticated())return startAuth();openModal(`<h2>Account MTG</h2><p>${safe(session.user.email)}</p><p class="muted">Analisi AI disponibile con la tua connessione Supabase.</p><button class="btn btn-outline" id="logOut">Esci</button>`);$('#logOut').onclick=async()=>{await supabase.auth.signOut();closeModal();render()}};$('#privacyBtn').onclick=()=>openModal(`<h2>Informazioni sul prototipo</h2><p>Mind The Gap è un prototipo di test. Nomi, ritratti, recensioni, prezzi dei servizi e report degli esperti sono simulati. I click di acquisto non comportano addebiti.</p><p>Le proprietà e i metadati restano salvati nel browser; i testi dei documenti vengono salvati in IndexedDB sul dispositivo. Quando richiedi un'analisi reale, i testi forniti sono trasmessi alla tua Edge Function Supabase e quindi a OpenAI.</p><p>Nessuna risposta sostituisce una verifica di regolarità urbanistica, catastale, giuridica o tecnica.</p><button class="btn btn-outline" data-close>Chiudi</button>`);$('#modal').onclick=e=>{if(e.target.matches('.modal-backdrop'))closeModal()};
render();initSupabase();
